import { Component, JSX, splitProps } from 'solid-js';

export interface BorderBeamProps extends JSX.HTMLAttributes<HTMLDivElement> {
  size?: number;
  duration?: number;
  borderWidth?: number;
  borderRadius?: number;
  colorFrom?: string;
  colorTo?: string;
  doubleBeam?: boolean;
  endOpacity?: number;
  opacity?: number;
  blur?: number;
}

export const BorderBeam: Component<BorderBeamProps> = (props) => {
  const [local, others] = splitProps(props, [
    'size',
    'duration',
    'borderWidth',
    'borderRadius',
    'colorFrom',
    'colorTo',
    'doubleBeam',
    'endOpacity',
    'opacity',
    'blur',
    'class',
  ]);

  const size = () => local.size ?? 200;
  const duration = () => local.duration ?? 8;
  const borderWidth = () => local.borderWidth ?? 2;
  const borderRadius = () => local.borderRadius ?? 16;
  const colorFrom = () => local.colorFrom ?? '#ffaa40';
  const colorTo = () => local.colorTo ?? '#9c40ff';
  const doubleBeam = () => local.doubleBeam ?? false;
  const endOpacity = () => local.endOpacity ?? 0;
  const opacity = () => local.opacity ?? 1;
  const blur = () => local.blur ?? 0;

  const endColor = () => {
    const clamped = Math.max(0, Math.min(1, endOpacity()));
    if (clamped <= 0) return 'transparent';
    if (clamped >= 1) return colorTo();
    return `color-mix(in srgb, ${colorTo()} ${Math.round(clamped * 100)}%, transparent)`;
  };

  const pathRadius = () => Math.min(local.size, 200);

  return (
    <div
      aria-hidden="true"
      class={`exhuma-border-beam pointer-events-none absolute inset-0 rounded-[inherit] ${local.class ?? ''}`}
      style={{
        border: `${borderWidth()}px solid transparent`,
        '-webkit-mask': 'linear-gradient(#fff 0 0) padding-box, linear-gradient(#fff 0 0)',
        '-webkit-mask-composite': 'destination-out',
        mask: 'linear-gradient(#fff 0 0) padding-box, linear-gradient(#fff 0 0)',
        'mask-composite': 'exclude',
        opacity: opacity() !== 1 ? opacity() : undefined,
        filter: blur() > 0 ? `blur(${blur()}px)` : undefined,
      }}
      {...others}
