export function initBorderBeam(selector = '[data-exhuma-border-beam]', options = {}) {
  const elements = document.querySelectorAll(selector);
  const cleanups = [];

  if (!document.getElementById('exhuma-border-beam-keyframes')) {
    const style = document.createElement('style');
    style.id = 'exhuma-border-beam-keyframes';
    style.textContent = `
      @keyframes exhuma-border-beam {
        from { offset-distance: 0%; }
        to { offset-distance: 100%; }
      }
      @media (prefers-reduced-motion: reduce) {
        .exhuma-border-beam-trace { animation-play-state: paused !important; }
      }
    `;
    document.head.appendChild(style);
  }

  elements.forEach((container) => {
    const size = parseFloat(container.getAttribute('data-size') || options.size || 200);
    const duration = parseFloat(container.getAttribute('data-duration') || options.duration || 8);
    const borderWidth = parseFloat(container.getAttribute('data-border-width') || options.borderWidth || 2);
    const borderRadius = parseFloat(container.getAttribute('data-border-radius') || options.borderRadius || 16);
    const colorFrom = container.getAttribute('data-color-from') || options.colorFrom || '#ffaa40';
    const colorTo = container.getAttribute('data-color-to') || options.colorTo || '#9c40ff';
    const doubleBeam = (container.getAttribute('data-double-beam') || options.doubleBeam) === 'true' || options.doubleBeam === true || false;
    const endOpacity = parseFloat(container.getAttribute('data-end-opacity') || options.endOpacity || 0);
    const opacity = parseFloat(container.getAttribute('data-opacity') || options.opacity || 1);
    const blur = parseFloat(container.getAttribute('data-blur') || options.blur || 0);

