import React, { useEffect, useRef } from 'react';
import { View, StyleSheet, Animated, Easing, type ViewProps } from 'react-native';

export interface BorderBeamProps extends ViewProps {
  size?: number;
  duration?: number;
  borderWidth?: number;
  borderRadius?: number;
  colorFrom?: string;
  colorTo?: string;
  doubleBeam?: boolean;
  opacity?: number;
}

export const BorderBeam: React.FC<BorderBeamProps> = ({
  size = 200,
  duration = 8,
  borderWidth = 2,
  borderRadius = 16,
  colorFrom = '#ffaa40',
  colorTo = '#9c40ff',
  doubleBeam = false,
  opacity = 1,
  style,
  ...props
}) => {
  const anim1 = useRef(new Animated.Value(0)).current;
  const anim2 = useRef(new Animated.Value(0.5)).current;

  useEffect(() => {
    const loop1 = Animated.loop(
      Animated.timing(anim1, {
        toValue: 1,
        duration: duration * 1000,
        easing: Easing.linear,
        useNativeDriver: true,
      })
    );
    loop1.start();

    let loop2: Animated.CompositeAnimation | null = null;
    if (doubleBeam) {
      loop2 = Animated.loop(
        Animated.timing(anim2, {
          toValue: 1.5,
          duration: duration * 1000,
          easing: Easing.linear,
          useNativeDriver: true,
        })
      );
      loop2.start();
    }

    return () => {
      loop1.stop();
      if (loop2) loop2.stop();
    };
  }, [duration, doubleBeam, anim1, anim2]);

  const rotate1 = anim1.interpolate({
    inputRange: [0, 1],
    outputRange: ['0deg', '360deg'],
  });

  const rotate2 = anim2.interpolate({
    inputRange: [0.5, 1.5],
    outputRange: ['180deg', '540deg'],
  });

  return (
    <View
      pointerEvents="none"
      style={[
        styles.container,
        {
          borderWidth,
          borderRadius,
          opacity: opacity !== 1 ? opacity : 1,
        },
        style,
      ]}
      {...props}
    >
      <Animated.View
        style={[
          styles.beam,
          {
            width: size,
            height: size,
            backgroundColor: colorFrom,
            transform: [{ rotate: rotate1 }],
          },
        ]}
      />
      {doubleBeam && (
        <Animated.View
          style={[
            styles.beam,
            {
              width: size,
              height: size,
              backgroundColor: colorTo,
              transform: [{ rotate: rotate2 }],
            },
          ]}
        />
      )}
    </View>
  );
};

